// src/components/AgentList.js
import React, { useState } from 'react';
import './AgentList.css';

// Dummy Data
const agentsData = [
  {
    name: "Adam Trantow",
    company: "Mohr, Langworth and Hills",
    role: "Sales Agent",
    email: "Adam.Trantow@test.com",
    mobile: "(942) 208-5834 x1417",
    verified: true,
    status: "Active",
  },
  {
    name: "Billy Stoltenberg",
    company: "Medhurst, Moore and Franey",
    role: "Sales Leader",
    email: "Billy.Stoltenberg@test.com",
    mobile: "(499) 633-7585",
    verified: true,
    status: "Locked",
  },
  // Add other agents as needed
];

export default function AgentList() {
  const [search, setSearch] = useState('');

  const filteredAgents = agentsData.filter(agent =>
    agent.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="agentlist-container">
      <div className="agentlist-header">
        <h2>Agents</h2>
        <button className="add-agent-btn">+ NEW AGENT</button>
      </div>
      <div className="agentlist-search">
        <input
          type="text"
          placeholder="Search user..."
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
      </div>
      <div className="agentlist-table-wrap">
        <table className="agentlist-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Company</th>
              <th>Role</th>
              <th>E-mail</th>
              <th>Mobile</th>
              <th>Verified</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {filteredAgents.map((agent, idx) => (
              <tr key={idx}>
                <td>{agent.name}</td>
                <td>{agent.company}</td>
                <td>{agent.role}</td>
                <td>{agent.email}</td>
                <td>{agent.mobile}</td>
                <td>
                  {agent.verified ? (
                    <span className="verified-check">&#10003;</span>
                  ) : (
                    <span className="not-verified">&#10007;</span>
                  )}
                </td>
                <td>
                  <span className={`status-badge ${agent.status === "Active" ? "active" : "locked"}`}>
                    {agent.status}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
